import test from "node:test";
import assert from "node:assert/strict";
import { HttpError, NotFoundError, ValidationError } from "../dist/errors.js";

test("HttpError carries status, message, and optional details", () => {
  const err = new HttpError(418, "teapot", { reason: "short and stout" });
  assert.ok(err instanceof Error);
  assert.equal(err.status, 418);
  assert.equal(err.message, "teapot");
  assert.deepEqual(err.details, { reason: "short and stout" });

  const plain = new HttpError(500, "oops");
  assert.equal(plain.details, undefined);
});

