import { test } from 'node:test';
import assert from 'node:assert/strict';
import express from 'express';
import { notesRouter } from '../dist/notes/notes.routes.js';
import { NotesStore } from '../dist/notes/notes.store.js';

function makeApp() {
  const app = express();
  app.use(express.json());
  app.use('/notes', notesRouter(new NotesStore(), 200));
  app.use((err, req, res, next) => {
    const status = err.statusCode || 500;
    res.status(status).json({ error: err.message, details: err.details });
  });
  return app;
}

test('POST /notes creates and GET /notes/:id returns it', async () => {
  const app = makeApp();
  const server = app.listen(0);
  const { port } = server.address();
  try {
    const base = `http://localhost:${port}`;
    const postRes = await fetch(`${base}/notes`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: 'Hello', body: 'World' }),
    });
    assert.strictEqual(postRes.status, 201);
    const created = await postRes.json();
    assert.strictEqual(created.title, 'Hello');

    const getRes = await fetch(`${base}/notes/${created.id}`);
    assert.strictEqual(getRes.status, 200);
    const fetched = await getRes.json();
    assert.strictEqual(fetched.id, created.id);
    assert.strictEqual(fetched.title, 'Hello');
  } finally {
    server.close();
  }
});

