import { test } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';

test('server.js starts and listens, logging its URL', async () => {
  let capturedServer;
  const originalListen = http.Server.prototype.listen;
  http.Server.prototype.listen = function (...args) {
    capturedServer = this;
    return originalListen.apply(this, args);
  };

  let loggedLine = '';
  let resolveLog;
  const logged = new Promise((resolve) => {
    resolveLog = resolve;
  });
  const originalLog = console.log;
  console.log = (msg) => {
    loggedLine = String(msg);
    resolveLog();
  };

  try {
    await import('../dist/server.js');
    await Promise.race([
      logged,
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error('timed out waiting for the server to log its URL')), 1500),
      ),
    ]);
  } finally {
    console.log = originalLog;
    http.Server.prototype.listen = originalListen;
  }

  assert.ok(capturedServer, 'expected the server to call listen()');
  assert.ok(capturedServer.listening, 'expected the server to be listening');

  const address = capturedServer.address();
  assert.equal(typeof address, 'object', 'expected server.address() to return connection info');
  assert.ok(address.port > 0, 'expected a listening port greater than 0');

  assert.match(
    loggedLine,
    /express-notes listening on http:\/\/localhost:\d+/,
    'expected a log message with the server URL',
  );
  assert.ok(
    loggedLine.includes(String(address.port)),
    'expected the logged URL to include the actual listening port',
  );

  const res = await fetch(`http://localhost:${address.port}/`);
  assert.ok(res.status >= 100 && res.status < 600, 'expected the server to respond to a request');

  await new Promise((resolve) => capturedServer.close(resolve));
});
